function open(){feedOffset=0;feedKey=null;readingPast=false;pastResume=false;nextBeatAt=performance.now()+Math.max(1600,life.chronicle.lastBeat?.waitMs||0);running=false;recordResume=false;endingPage=life.chronicle.endingPage||0;closeModal();clock=resetClock();limit=40;folded=null;tab='dashboard';portraitKey=null;$('intro').hidden=true;$('game').hidden=false;switchTab('dashboard')}
$('birth').onclick=()=>{if(life?.alive&&!confirm('현재 삶 대신 새 삶을 시작할까요? 기록이 필요하면 먼저 내보내 주세요.'))return;if(resultTimer)clearTimeout(resultTimer);resultTimer=null;replay=null;endingPage=0;recordResume=false;closeModal();life=createLife(crypto.getRandomValues(new Uint32Array(1))[0],crypto.randomUUID());setBirthDate(life,new Intl.DateTimeFormat('en-CA',{timeZone:'Asia/Seoul',year:'numeric',month:'2-digit',day:'2-digit'}).format(new Date()));save();open()};
$('resume').onclick=()=>{try{life=restore(localStorage.getItem(key));open()}catch{status('기록을 불러오지 못했습니다.');alert('기록을 불러오지 못했습니다.')}};
function goHome(){running=false;replay=null;clock=resetClock();if(resultTimer)clearTimeout(resultTimer);resultTimer=null;save();closeModal();for(const id of ['game','birth-screen','ending-screen','replay-screen'])$(id).hidden=true;$('intro').hidden=false}
$('home').onclick=goHome;$('birth-home').onclick=goHome;$('ending-home').onclick=goHome;
$('pause').onclick=()=>{if(simulationMode(life)==='direct'){$('next').onclick();return}if(readingPast){$('latest-records').onclick();return}if(life.pending&&life.mode==='intervene'){folded=null;render();return}if(life.presentation||life.chronicle.reading)return;if(tab==='timeline'&&life.chronicle.preferences.pauseOnRecords){recordResume=!recordResume;status(recordResume?'기록을 닫으면 다시 진행합니다.':'기록을 닫아도 멈춰 있습니다.');return}running=!running;nextBeatAt=performance.now()+800;clock=resetClock();render()};
$('next').onclick=()=>{if(life.pending||life.presentation||life.chronicle.reading||!life.alive)return;running=false;const beat=nextStoryBeat(life);nextBeatAt=performance.now()+beat.waitMs;feedOffset=0;feedKey=null;save();render()};
$('mode').onchange=()=>{life.mode=$('mode').value;if(life.mode==='observe'){life.chronicle.preferences.progressMode='observe';life.chronicle.preferences.pace='observe';running=!life.presentation&&!life.chronicle.reading;}else if(simulationMode(life)==='observe'){life.chronicle.preferences.progressMode='story';life.chronicle.preferences.pace='story';}nextBeatAt=performance.now()+800;feedKey=null;folded=null;save();render()};
$('pace').onchange=()=>{const mode=$('pace').value;life.chronicle.preferences.progressMode=mode;life.chronicle.preferences.pace=mode==='observe'?'observe':'story';life.mode=mode==='observe'?'observe':'intervene';if(mode==='direct')running=false;nextBeatAt=performance.now()+800;feedKey=null;save();render()};$('pause-records').onchange=()=>{life.chronicle.preferences.pauseOnRecords=$('pause-records').checked;save()};$('speed').onchange=()=>{nextBeatAt=Math.max(nextBeatAt,performance.now()+600)};
$('dismiss').onclick=()=>{folded=decisionUid(life)||(life.presentation||life.chronicle.reading)?.id;closeModal();render()};$('modal-shade').onclick=()=>$('dismiss').onclick();$('reopen').onclick=()=>{folded=null;render()};$('continue-story').onclick=finishResult;
for(const name of ['dashboard','timeline','relations','status','world'])$('tab-'+name).onclick=()=>switchTab(name);$('all-records').onclick=()=>switchTab('timeline');$('save').onclick=save;$('older').onclick=()=>{feedOffset+=40;readingPast=true;pastResume=pastResume||running;running=false;feedKey=null;timeline();$('latest-anchor').scrollIntoView?.({block:'start'})};$('newer').onclick=()=>{feedOffset=Math.max(0,feedOffset-40);feedKey=null;timeline()};
$('export').onclick=()=>{const url=URL.createObjectURL(new Blob([serialize(life)],{type:'application/json'})),a=el('a');a.href=url;a.download=`dogs-life-${life.seed}.json`;a.click();setTimeout(()=>URL.revokeObjectURL(url),1000)};
$('import').onclick=()=>$('file').click();$('file').onchange=async e=>{try{const file=e.target.files[0];if(!file)return;if(file.size>5e6)throw Error();const candidate=restore(await file.text());if(resultTimer)clearTimeout(resultTimer);resultTimer=null;life=candidate;save();open()}catch{status('호환되지 않거나 손상된 기록입니다.')}e.target.value=''};
// Escape folds a decision; Tab remains inside the visible modal.
document.addEventListener?.('keydown',e=>{if($('modal').hidden)return;if(e.key==='Escape'){$('dismiss').onclick();return}if(e.key==='Tab'){const buttons=Array.from($('modal').querySelectorAll?.('button:not([disabled])')||[]).filter(b=>!b.closest('[hidden]'));if(!buttons.length)return;const first=buttons[0],last=buttons.at(-1);if(e.shiftKey&&document.activeElement===first){e.preventDefault();last.focus()}else if(!e.shiftKey&&document.activeElement===last){e.preventDefault();first.focus()}}});
try{$('resume').hidden=!localStorage.getItem(key)}catch{}
setInterval(()=>{const now=performance.now();if(!life||!running||life.chronicle.phase!=='living'||simulationMode(life)==='direct'||life.presentation||life.chronicle.reading||replay||readingPast||tab==='timeline'&&life.chronicle.preferences.pauseOnRecords||now<nextBeatAt)return;const beat=nextStoryBeat(life);const delay=beatDelay(beat,$('speed').value);nextBeatAt=now+delay;life.chronicle.lastBeat={day:life.day,waitMs:delay};running=life.alive&&(!life.pending||life.mode==='observe');if(!life.alive){life.chronicle.phase='ending';life.chronicle.endingSeen=false;endingPage=0;running=false}if(beat.events.length||!running)save();render()},TIME_CONFIG.pollMs);
