function atlasNode(pic){const box=el('figure',null,'life-photo'),viewport=el('div',null,'atlas-window'),img=el('img');img.src=pic.url;img.alt=pic.alt;img.decoding='async';Object.assign(img.style,atlasFrame(pic));viewport.append(img);box.append(viewport);return box}
