function hideScreens(){for(const id of ['birth-screen','ending-screen','replay-screen'])$(id).hidden=true}
function routeScreens(){hideScreens();if(replay){$('game').hidden=true;$('replay-screen').hidden=false;renderReplay();return true}const c=life.chronicle;if(!life.alive&&!c.endingSeen){running=false;$('game').hidden=true;$('ending-screen').hidden=false;closeModal();renderEnding();return true}if(c.phase==='birth'&&!c.birthAcknowledged){running=false;$('game').hidden=true;$('birth-screen').hidden=false;closeModal();renderBirth();return true}$('game').hidden=false;return false}
function renderBirth(){const c=life.chronicle,b=c.birth;$('birth-date').textContent=`${dayDate(life,0)} · ${b.country} · 개 / ${life.breed}`;$('birth-place').textContent=b.place;$('birth-portrait').replaceChildren(visualNode(life,{id:'birth',day:0}));$('birth-image-note').textContent='출생 컷은 외형 참고 표현이며, 아래 환경은 이 삶의 출생 설정입니다.';$('birth-story').textContent=birthStory(life);$('birth-facts').replaceChildren();const parent=p=>!p.known?'정보 미상':`${p.species} · ${p.breed||'품종 미상'}${p.ageYears?' · '+p.ageYears+'살':''}${p.features?' · '+(p.features===life.appearance.lookId?lookOf(life).label:p.features):''} · ${p.alive===true?'출생 당시 생존':'생존 여부 미상'} · ${p.together?'곁에 있음':'함께 살지 않음'}`;for(const[k,v]of [['출생 환경',`${homeName[b.home]||b.home} · ${b.place}`],['어미',parent(b.mother)],['아비',parent(b.father)],['형제',b.siblings==null?'혈연 형제 정보 미상':`${b.siblings}마리 · 나를 포함해 ${b.litterSize}마리`],['처음의 몸',b.body],['돌봄',b.support],['초기 위험',b.risk],['건강 지표',b.health==null?'이전 기록 미상':`${b.health}/100 · 게임 설정`]])$('birth-facts').append(el('dt',k),el('dd',v));}
function renderEnding(){if(life.chronicle.endingPage!==endingPage){life.chronicle.endingPage=endingPage;save()}const data=endingData(life);for(let i=0;i<4;i++)$('end-tab-'+i).setAttribute('aria-pressed',String(i===endingPage));$('ending-title').textContent=['마지막 순간을 곁에서','살아온 날들을 돌아봅니다.','기억으로 남은 발자국','한 생의 작은 이야기'][Math.min(3,endingPage)];const area=$('ending-content');area.replaceChildren();if(endingPage===0){const grid=el('div',null,'cinematic-grid'),picture=el('div'),text=el('div');picture.append(visualNode(life,{day:life.day,id:'death'}),el('small','마지막 성장 단계의 외형 참고 컷 · 실제 마지막 순간을 촬영한 이미지가 아닙니다.'));const finalScene=visualFor(life,{day:life.day,id:'death'}).scene;if(finalScene){const context=atlasNode(finalScene);context.classList.add('context-cut');picture.append(context)}text.append(el('h2',`${life.breed} · ${data.age}`),el('p',`${data.deathDate} · ${data.place}`),el('p',`사인 · ${data.cause}`),el('p',data.last));grid.append(picture,text);area.append(grid)}else if(endingPage===1){const facts=el('dl',null,'facts');for(const[k,v]of [['출생지',`${data.birth.country} · ${data.birth.place}`],['최종 환경',data.place],['살아온 날',`${life.day}일 · ${data.age}`],['곁의 존재',data.relations.map(r=>r.name).join(', ')||'기록된 관계 없음'],['남은 기록',`${life.log.length}개 기록 · 기억 ${life.memories.length}개`]])facts.append(el('dt',k),el('dd',v));area.append(facts);for(const e of data.memories.filter(e=>['adopt','moving','companion-close','litter-born','reunion'].includes(e.id)).slice(0,8))area.append(el('p',`${age(e.day)} · ${e.text}`))}else if(endingPage===2){const list=el('ol',null,'end-memory');for(const e of data.memories){const li=el('li');li.append(el('small',`${age(e.day)} · ${dayDate(life,e.day)}`),el('p',e.text));list.append(li)}area.append(list)}else if(endingPage===3)area.append(el('p',data.biography,'biography'));else renderGallery(area);$('ending-prev').disabled=endingPage===0;$('ending-next').disabled=endingPage>=3;$('ending-next').textContent=endingPage===2?'작은 전기 읽기 ↗':'다음 장면 ↗';}
function renderGallery(area){$('ending-title').textContent='그날의 모습과 기록';const grid=el('div',null,'gallery'),seen=new Set();for(const e of memoryTimeline(life)){if(!['birth','eyes','walking','growing-body','maturity','birthday','aging','adopt','moving','death'].includes(e.id))continue;const v=visualFor(life,e),key=v.portrait?`${v.portrait.url}:${v.portrait.x}:${v.portrait.y}`:v.phase;if(seen.has(key))continue;seen.add(key);const f=el('figure');if(v.portrait)f.append(atlasNode(v.portrait));else f.append(el('div',e.text,'missing-scene'));f.append(el('figcaption',`${age(e.day)} · ${v.portrait?'제작 성장 컷':'전용 이미지가 없어 실제 기록으로 표시'}`));grid.append(f)}area.append(grid)}
function renderReplay(){const e=replay.records[replay.index];$('replay-age').textContent=age(e.day);$('replay-picture').replaceChildren(visualNode(life,e));$('replay-story').textContent=e.text;$('replay-position').textContent=`${replay.index+1} / ${replay.records.length} · 저장된 삶을 읽습니다. 실제 생애 상태는 바뀌지 않습니다.`;$('replay-toggle').textContent=replay.playing?'❚❚ 멈춤':'▶ 다시 보기';$('replay-prev').disabled=replay.index===0;$('replay-next').disabled=replay.index===replay.records.length-1;}
$('start-life').onclick=()=>{life.chronicle.phase='living';life.chronicle.birthAcknowledged=true;const b=life.chronicle.birth;if(b.father.known&&!life.relations.some(r=>r.id==='father'))life.relations.push({id:'father',kind:'father',name:'아비',area:life.areaId,familiarity:b.father.together?30:0,trust:b.father.together?35:0,caution:20,conflict:0,contacts:b.father.together?1:0,lastContact:b.father.together?0:null,active:b.father.together,details:`출생 당시 ${b.father.ageYears}살 · ${b.father.breed}`});save();clock=resetClock();nextBeatAt=performance.now()+1600;running=simulationMode(life)!=='direct';render()};
for(let i=0;i<4;i++)$('end-tab-'+i).onclick=()=>{endingPage=i;renderEnding()};$('ending-prev').onclick=()=>{endingPage=Math.max(0,endingPage-1);renderEnding()};$('ending-next').onclick=()=>{endingPage=Math.min(3,endingPage+1);renderEnding()};$('ending-gallery').onclick=()=>{endingPage=4;renderEnding()};
$('ending-timeline').onclick=()=>{life.chronicle.endingSeen=true;save();hideScreens();switchTab('timeline')};$('show-ending').onclick=()=>{life.chronicle.endingSeen=false;endingPage=0;save();render()};$('ending-export').onclick=()=>$('export').onclick();$('ending-share').onclick=async()=>{try{await downloadLifeCard(life)}catch{alert('이미지 카드를 저장하지 못했습니다. 생애 기록 파일은 저장할 수 있습니다.')}};$('new-life').onclick=()=>$('birth').onclick();
$('replay-life').onclick=()=>{running=false;const records=life.log.filter(e=>e.id!=='choice'&&e.id!=='decision'&&!e.resolvedDecisionUid);replay={records,index:0,playing:false,elapsed:0};render()};$('close-replay').onclick=()=>{replay=null;render()};$('replay-prev').onclick=()=>{replay.index=Math.max(0,replay.index-1);replay.elapsed=0;renderReplay()};$('replay-next').onclick=()=>{replay.index=Math.min(replay.records.length-1,replay.index+1);replay.elapsed=0;renderReplay()};$('replay-toggle').onclick=()=>{replay.playing=!replay.playing;renderReplay()};setInterval(()=>{if(!replay?.playing)return;replay.elapsed+=1000;if(replay.elapsed<readingMs(replay.records[replay.index].text))return;replay.elapsed=0;if(replay.index===replay.records.length-1)replay.playing=false;else replay.index++;renderReplay()},1000);

$('record-query').oninput=()=>{recordQuery=$('record-query').value;feedOffset=0;feedKey=null;timeline()};$('record-type').onchange=()=>{recordType=$('record-type').value;feedOffset=0;feedKey=null;timeline()};
$('latest-records').onclick=()=>{readingPast=false;storyFilter=null;feedOffset=0;feedKey=null;if(pastResume&&!life.pending&&!life.presentation&&!life.chronicle.reading)running=true;pastResume=false;nextBeatAt=performance.now()+1200;timeline();$('latest-anchor').scrollIntoView?.({behavior:'smooth',block:'start'});render()};
window.addEventListener('scroll',()=>{if(!life||!['dashboard','timeline'].includes(tab)||!life.chronicle.preferences.pauseOnRecords)return;const rect=$('latest-anchor').getBoundingClientRect?.();if(rect&&rect.top< -80&&!readingPast){readingPast=true;pastResume=pastResume||running;running=false;$('latest-records').hidden=false;status('과거 기록을 읽는 동안 멈춰 있습니다.');render()}},{passive:true});
